(function(root){
 const add=(d,n)=>{const x=new Date(d+'T00:00:00Z');x.setUTCDate(x.getUTCDate()+n);return x.toISOString().slice(0,10);};
 const monday=d=>add(d,-((new Date(d+'T00:00:00Z').getUTCDay()+6)%7));
 function columns(data){const result=[];for(const c of data.classes){let group=result.find(g=>g.name===c.name);if(group)group.ids.push(c.id);else result.push({id:c.id,name:c.name,ids:[c.id]});}return result;}
 function weeks(data){const rows=[];for(let start=monday(data.termStart),number=1;start<=data.termEnd;start=add(start,7),number++)rows.push({start,end:add(start,6),from:start<data.termStart?data.termStart:start,to:add(start,4)>data.termEnd?data.termEnd:add(start,4),number,exam:data.exams.some(e=>e.date<=add(start,6)&&e.end>=start)});return rows;}
 function cell(data,start,column){const explicit=data.weeklyProgress?.[start]?.classes;if(explicit&&Object.hasOwn(explicit,column.id))return explicit[column.id];return Object.values(data.notes).filter(n=>column.ids.includes(n.classId)&&n.date>=start&&n.date<=add(start,6)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(n=>`${n.date.slice(5).replace('-','/')} ${n.content}${n.homework?'\n提醒：'+n.homework:''}`).join('\n\n');}
 function reminders(data,start){const saved=data.weeklyProgress?.[start];if(saved&&Object.hasOwn(saved,'reminder'))return saved.reminder;const end=add(start,6),items=[];for(const e of data.exams)if(e.date<=end&&e.end>=start)items.push(`${e.date.slice(5).replace('-','/')}–${e.end.slice(5).replace('-','/')} ${e.name}`);for(const e of data.events)if(e.date>=start&&e.date<=end)items.push(`${e.date.slice(5).replace('-','/')} ${e.title}`);return [...new Set(items)].join('\n');}
 function valid(data){const value=data.weeklyProgress;if(value===undefined)return true;if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).length>60)return false;const starts=new Set(weeks(data).map(w=>w.start)),ids=new Set(data.classes.map(c=>c.id));return Object.entries(value).every(([date,row])=>starts.has(date)&&row&&typeof row==='object'&&!Array.isArray(row)&&(!Object.hasOwn(row,'reminder')||typeof row.reminder==='string'&&row.reminder.length<=12000)&&(!Object.hasOwn(row,'classes')||row.classes&&typeof row.classes==='object'&&!Array.isArray(row.classes)&&Object.entries(row.classes).every(([id,text])=>ids.has(id)&&typeof text==='string'&&text.length<=12000)));}
 const api={monday,columns,weeks,cell,reminders,valid};if(typeof module!=='undefined')module.exports=api;else root.WeeklyProgress=api;
})(globalThis);
